insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"noun_repair_q01_finish","locale":"he","line_order":0,"content":"תודה! עכשיו הספר כבר הרבה יותר ברור.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_finish","locale":"he","line_order":1,"content":"אפשר לזהות בו אנשים, חפצים, מקומות וחיות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_finish","locale":"he","line_order":2,"content":"קחו את ה Gem לילד ליד השער.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_finish","locale":"he","line_order":3,"content":"גם לו יש כמה שמות שקשה לקרוא.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_start","locale":"he","line_order":0,"content":"אוי לא. בספר המילים שלי חסרים שמות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_start","locale":"he","line_order":1,"content":"Noun הוא שם של אדם, חיה, מקום או דבר.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_start","locale":"he","line_order":2,"content":"למשל, boy, cat, park ו table הם nouns.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_start","locale":"he","line_order":3,"content":"בלי השמות האלה קשה להבין מה רואים בתמונה.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_start","locale":"he","line_order":4,"content":"בואו נחזיר לספר את השמות שנעלמו.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_finish","locale":"he","line_order":0,"content":"יש! עכשיו אפשר לקרוא את השמות על התיק.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_finish","locale":"he","line_order":1,"content":"אני רואה שוב את המילים bag, book, pen ו dog.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_finish","locale":"he","line_order":2,"content":"קחו את ה Power Stone לחקלאי בשוק.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_finish","locale":"he","line_order":3,"content":"הוא צריך עזרה עם השלטים שלו.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_start","locale":"he","line_order":0,"content":"שלום. כמה תוויות בתיק שלי נקרעו.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_start","locale":"he","line_order":1,"content":"אני יודע מה יש בתיק, אבל קשה לקרוא את השמות באנגלית.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_start","locale":"he","line_order":2,"content":"עזרו לי להחזיר לכל דבר את השם הנכון.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_start","locale":"he","line_order":3,"content":"אחר כך חזרו וספרו לי מה הצלחתם לתקן.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_finish","locale":"he","line_order":0,"content":"מצוין. עכשיו הלקוחות יכולים לקרוא את השלטים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_finish","locale":"he","line_order":1,"content":"הם יודעים מהו apple, מהו bread ומהו cup.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_finish","locale":"he","line_order":2,"content":"קחו את ה Ancient Rune לאישה הזקנה.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_finish","locale":"he","line_order":3,"content":"גם במטבח שלה חסרים שמות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_start","locale":"he","line_order":0,"content":"ברוכים הבאים לשוק.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_start","locale":"he","line_order":1,"content":"כמה שלטים ניזוקו, והלקוחות לא בטוחים מה נמצא בכל דוכן.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_start","locale":"he","line_order":2,"content":"עזרו לי להחזיר לשוק את שמות הפירות, האוכל וכלי העבודה.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_start","locale":"he","line_order":3,"content":"אחרי שתסיימו, חזרו אליי.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_finish","locale":"he","line_order":0,"content":"תודה. עכשיו אפשר לזהות את ה chef, ה spoon וה plate.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_finish","locale":"he","line_order":1,"content":"המטבח שוב מסודר, וכולם יודעים מה לעשות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_finish","locale":"he","line_order":2,"content":"קחו את ה Gem לפרופסור המשוגע.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_finish","locale":"he","line_order":3,"content":"הוא מצא עוד תוויות בארמון.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_start","locale":"he","line_order":0,"content":"במטבח שלי נפלו הרבה תוויות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_start","locale":"he","line_order":1,"content":"עכשיו קשה לדעת איך קוראים לכל כלי ולכל תפקיד.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_start","locale":"he","line_order":2,"content":"עזרו לי להחזיר את השמות, כדי שנוכל לעבוד במטבח.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_start","locale":"he","line_order":3,"content":"אחרי שתסיימו, חזרו אליי.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_finish","locale":"he","line_order":0,"content":"נפלא. עכשיו תוויות הארמון ברורות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_finish","locale":"he","line_order":1,"content":"אפשר לזהות את ה queen, ה guard ואת שאר הדברים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_finish","locale":"he","line_order":2,"content":"קחו את ה Power Stone למאיה.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_finish","locale":"he","line_order":3,"content":"היא מחכה לכם עם הדף האחרון של הספר.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_start","locale":"he","line_order":0,"content":"מצאתי תוויות ישנות מהארמון, אבל חלק מהאותיות חסרות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_start","locale":"he","line_order":1,"content":"בלי השמות הנכונים קשה לזהות את המקומות, התפקידים והחפצים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_start","locale":"he","line_order":2,"content":"עזרו לי להשלים את השמות של castle, tower, throne ו crown.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_start","locale":"he","line_order":3,"content":"אחרי שתסיימו, חזרו אליי עם ה Power Stone.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_finish","locale":"he","line_order":0,"content":"כל הכבוד! השמות חזרו לספר.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_finish","locale":"he","line_order":1,"content":"עכשיו אתם יודעים לזהות, לאיית ולקרוא nouns באנגלית.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_finish","locale":"he","line_order":2,"content":"Noun Repair Shop פתוח שוב.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_finish","locale":"he","line_order":3,"content":"תודה על העזרה. קחו את הפרס.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_start","locale":"he","line_order":0,"content":"חזרתם בזמן. ספר המילים כמעט מוכן.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_start","locale":"he","line_order":1,"content":"לפני שנפתח את החנות, נבדוק שאתם מזהים nouns.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_start","locale":"he","line_order":2,"content":"Nouns יכולים להיות אנשים, חיות, מקומות או דברים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_start","locale":"he","line_order":3,"content":"אחרי שתסיימו, הספר יוכל להיפתח מחדש.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
